mapper.select:
/* SeparateMngMapper.selectSeparateList : 별도관리물품해제신고 List */
SELECT * FROM ( SELECT edi.EDI_JOB_NO ,ROW_NUMBER() OVER(PARTITION BY edi.EDI_JOB_NO,od.OD_JOB_NO ORDER BY edi.EDI_JOB_NO,od.OD_JOB_NO) AS OD_NUM ,edi.ENT_CODE ,edi.ENT_BUSINESS_CODE ,od.OD_JOB_NO ,od.BOUND ,od.BOUND_TYPE ,edi.EDI_DOC_NO ,edi.ISSUE_DATE ,edi.EDI_STATUS ,edi.EDI_SEND_DATE ,edi.EDI_RECEIPT_DATE ,edi.EDI_RESULT_DATE ,edi.REGISTER_DATE_TIME AS EDI_REGISTER_DATE_TIME ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = edi.ENT_CODE AND USER_ID = edi.REGISTER_USER_ID) AS REGISTER_USER_NAME ,odAdd.CLEARANCE_RECEIPT_DATE ,od.PO_NO ,od.CD_TYPE ,od.MBL_NO ,od.HBL_NO ,od.MASTER_OD_JOB_NO ,odAdd.DELIVERY_DATE ,od.DELIVERY_CODE ,od.DELIVERY_NAME ,CONCAT(ISNULL(od.CONSIGNEE_ADDRESS, ''), ISNULL(od.CONSIGNEE_ADDRESS_A, ''), ISNULL(od.CONSIGNEE_ADDRESS_B, ''), ISNULL(od.CONSIGNEE_ADDRESS_C, ''), ISNULL(od.CONSIGNEE_ADDRESS_D, '')) AS CONSIGNEE_ADDRESS ,od.DELIVERY_ADDRESS_CHANGED ,od.DELIVERY_REASON_CHANGED ,od.CONSIGNEE_NAME ,od.COMMODITY_ITEM ,od.CUSTOMS_CODE ,od.ORIG_CODE ,od.VESSEL_FLIGHT ,odAdd.SIMPLE_REPORT_DATE ,od.REGISTER_DATE_TIME ,spItem.AR_DATE ,mod.MRN ,mod.MSN ,od.HSN ,spItem.FLIGHT_NO ,spItem.ITEM_DESC ,spItem.GWT ,spItem.PIECES ,SUM(spItem.GWT) OVER(PARTITION BY edi.EDI_JOB_NO,od.OD_JOB_NO ORDER BY edi.EDI_JOB_NO,od.OD_JOB_NO) AS ITEM_GWT ,SUM(spItem.PIECES) OVER(PARTITION BY edi.EDI_JOB_NO,od.OD_JOB_NO ORDER BY edi.EDI_JOB_NO,od.OD_JOB_NO) AS ITEM_PIECES ,COUNT(*) OVER(PARTITION BY edi.EDI_JOB_NO,od.OD_JOB_NO ORDER BY edi.EDI_JOB_NO,od.OD_JOB_NO) AS ITEM_CNT FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL odAdd ON od.OD_JOB_NO = odAdd.OD_JOB_NO INNER JOIN TB_ECM_OD_SPECIAL_ITEM spItem ON od.OD_JOB_NO = spItem.OD_JOB_NO INNER JOIN TB_ECM_OD mod ON od.MASTER_OD_JOB_NO = mod.OD_JOB_NO
INNER JOIN TB_EDI_LINKED edi ON edi.OD_JOB_NO = od.MASTER_OD_JOB_NO AND edi.EDI_DOC_NO = odAdd.SPECIAL_ITEM_DOC_NO
LEFT OUTER JOIN TB_EDI_LINKED edi ON edi.OD_JOB_NO = od.MASTER_OD_JOB_NO AND edi.EDI_DOC_NO = odAdd.SPECIAL_ITEM_DOC_NO
WHERE od.ENT_CODE = #{srchEntCode}
AND edi.EDI_JOB_NO IS NULL
AND edi.EDI_JOB_NO IS NOT NULL AND odAdd.SPECIAL_ITEM_DOC_NO = edi.EDI_DOC_NO
AND od.CD_TYPE = #{srchCdType}
AND ${srchNoType} LIKE CONCAT('%',#{srchNo},'%')
AND (edi.EDI_STATUS IS NOT NULL AND edi.EDI_STATUS <> '')
AND (edi.EDI_STATUS IS NULL OR edi.EDI_STATUS = '')
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})
AND edi.EDI_DOC_NO = #{ediDocNo}
) A WHERE OD_NUM = 1

mapper.insert:
/* SeparateMngMapper.insertSeparateMng : 별도관리물품해제신고 insert */
INSERT INTO TB_EDI_LINKED(
	EDI_JOB_NO
	,ENT_CODE
	,ENT_BUSINESS_CODE
	,OD_JOB_NO
	,BOUND
	,BOUND_TYPE
	,EDI_CODE
	,EDI_DOC_NO	
	,ISSUE_DATE
	,EDI_STATUS
	,EDI_PORTAL_MAILBOX_ID
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
)VALUES(
	 #{ediJobNo}
	,#{entCode}
	,#{entBusinessCode}
	,#{MASTER_OD_JOB_NO}
	,#{BOUND}
	,#{BOUND_TYPE}
	,'GOVCBRDAX'
	,#{ediDocNo}
	,#{issueDate}
	,NULL
	,#{EDI_PORTAL_MAILBOX_ID}
	,#{registerUserId}
	,DATEADD(HOUR, ${gmtTime}, GETDATE())
)

/* SeparateMngMapper.updateSeparateJob : 별도관리물품해제신고  insert */
UPDATE TB_ECM_OD_ADDITIONAL
SET SPECIAL_ITEM_DOC_NO = #{ediDocNo}
WHERE OD_JOB_NO IN(#{item.OD_JOB_NO})

mapper.delete:
/* SeparateMngMapper.deleteBatchSeparateMng : 별도관리물품해제신고 delete */
		
	
	
		DELETE TB_EDI_LINKED
		WHERE EDI_DOC_NO = #{item.ediDocNo};
		UPDATE TB_ECM_OD_ADDITIONAL SET
			   SPECIAL_ITEM_DOC_NO = NULL
		WHERE SPECIAL_ITEM_DOC_NO = #{item.ediDocNo};
	
	
		UPDATE TB_ECM_OD_ADDITIONAL 	
		SET SPECIAL_ITEM_DOC_NO = NULL
		WHERE OD_JOB_NO = #{item.odJobNo};
